#include <iostream>

struct Device { int id = 0; };
struct Input : virtual Device {};
struct Output : virtual Device {};
struct IO : Input, Output {};

int main() {
  IO io;
  Input& input = io;
  Output& output = io;
  input.id = 7;
  std::cout << (&input.id == &output.id) << ' ' << output.id;
}
